def read_df_by_path(p):
    p=Path(p)
    enc='utf-16' if p.read_bytes().startswith(b'\xff\xfe') else 'utf-8'
    with open(p, encoding=enc) as f:
        for _ in range(3): next(f)
        h=next(f)
    sep=';' if h.count(';')>h.count(',') else ','
    kwargs=dict(skiprows=3, sep=sep, encoding=enc, engine='python')
    if sep==';': kwargs.update(decimal=',', thousands='.')
    return pd.read_csv(p, **kwargs)
